std::pair<int, int> pairWithSum(const std::vector<int>& a, int target, Recorder& rec) {
    int left = 0;
    int right = static_cast<int>(a.size()) - 1;
    while (left < right) {
        int sum = a[left] + a[right];
        if (sum == target) return {left, right};
        if (sum < target) ++left;  // need a bigger sum
        else --right;              // need a smaller sum
    }
    return {-1, -1};
}

search.binary.code:
int binarySearch(const std::vector<int>& a, int target, Recorder& rec) {
    int lo = 0;
    int hi = static_cast<int>(a.size()) - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;  // same as (lo+hi)/2 but cannot overflow
        if (a[mid] == target) {
            return mid;
        }
        if (a[mid] < target) {
            lo = mid + 1;  // target is bigger: throw away the left half
        } else {
            hi = mid - 1;  // target is smaller: throw away the right half
        }
    }
    return -1;
}

