slot.alias.code:
AliasTable::AliasTable(const std::vector<std::uint32_t>& weights)
    : prob_(weights.size(), 0.0), alias_(weights.size(), 0) {
    const std::size_t n = weights.size();
    const double total = std::accumulate(weights.begin(), weights.end(), 0.0);
    if (n == 0 || total <= 0) throw std::invalid_argument("AliasTable needs positive weights");

    // Scale so the average column height is exactly 1.
    std::vector<double> scaled(n);
    std::vector<std::size_t> small, large;
    for (std::size_t i = 0; i < n; ++i) {
        scaled[i] = static_cast<double>(weights[i]) * static_cast<double>(n) / total;
        (scaled[i] < 1.0 ? small : large).push_back(i);
    }
    // Fill each short column to height 1 with a piece of a tall one.
    while (!small.empty() && !large.empty()) {
        const std::size_t s = small.back();
        small.pop_back();
        const std::size_t l = large.back();
        prob_[s] = scaled[s];
        alias_[s] = l;
        scaled[l] -= 1.0 - scaled[s];  // l donated the gap
        if (scaled[l] < 1.0) {
            large.pop_back();
            small.push_back(l);
        }
    }
    // Leftovers are (up to rounding) exactly 1: they need no partner.
    for (std::size_t i : large) { prob_[i] = 1.0; alias_[i] = i; }
    for (std::size_t i : small) { prob_[i] = 1.0; alias_[i] = i; }
}

slot.flood_fill.code:
// Breadth-first search: start at one cell, visit its matching neighbours,
// then THEIR neighbours... A queue keeps the "to visit" cells in order.
std::vector<std::vector<std::pair<int, int>>> findClusters(const Grid& grid, int minSize) {
    const int rows = static_cast<int>(grid.size());
    const int cols = rows ? static_cast<int>(grid[0].size()) : 0;
    std::vector<std::vector<bool>> seen(rows, std::vector<bool>(cols, false));
    std::vector<std::vector<std::pair<int, int>>> clusters;
    const int dr[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};  // up, down, left, right

    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (seen[r][c] || grid[r][c] < 0) continue;
            const int sym = grid[r][c];
            std::vector<std::pair<int, int>> cluster;
            std::queue<std::pair<int, int>> todo;
            todo.push({r, c});
            seen[r][c] = true;
            while (!todo.empty()) {
                auto [cr, cc] = todo.front();
                todo.pop();
                cluster.push_back({cr, cc});
                for (int d = 0; d < 4; ++d) {
                    const int nr = cr + dr[d], nc = cc + dc[d];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;  // off the grid
                    if (seen[nr][nc] || grid[nr][nc] != sym) continue;
                    seen[nr][nc] = true;  // mark when QUEUED, so nothing is queued twice
                    todo.push({nr, nc});
                }
            }
            if (static_cast<int>(cluster.size()) >= minSize) clusters.push_back(cluster);
        }
    }
    return clusters;
}

slot.gravity.code:
// Cascades: winning symbols vanish and everything above falls down.
// Per column, a "write" index walks up from the bottom (two pointers!).
int applyGravity(Grid& grid) {
    const int rows = static_cast<int>(grid.size());
    const int cols = rows ? static_cast<int>(grid[0].size()) : 0;
    int empty = 0;
    for (int c = 0; c < cols; ++c) {
        int write = rows - 1;
        for (int read = rows - 1; read >= 0; --read) {
            if (grid[read][c] >= 0) grid[write--][c] = grid[read][c];
        }
        for (int r = write; r >= 0; --r) {
            grid[r][c] = -1;  // these cells are now empty at the top
            ++empty;
        }
    }
    return empty;
}

slot.payline.code:
// Left to right: the first non-wild symbol decides what the line is
// "about"; count how many reels in a row match it (wilds count too).
LineResult evaluateLine(const ReelGame& g, const Screen& s, const std::vector<int>& rowOnReel) {
    const int reels = static_cast<int>(rowOnReel.size());
    int symbol = g.wild;
    for (int k = 0; k < reels; ++k) {
        const int sym = s[rowOnReel[k]][k];
        if (sym != g.wild) { symbol = sym; break; }
    }
    int count = 0;
    while (count < reels) {
        const int sym = s[rowOnReel[count]][count];
        if (sym != symbol && sym != g.wild) break;  // chain broken
        ++count;
    }
    const int pay = (symbol >= 0) ? g.paytable[symbol][count] : 0;
    return {symbol, count, pay};
}

slot.pick_binary.code:
// First running total that is GREATER than r. Totals [40, 70, 90, 100]:
// r = 0..39 -> 0,  r = 40..69 -> 1,  r = 70..89 -> 2,  r = 90..99 -> 3
std::size_t pickBinary(const std::vector<std::uint64_t>& prefix, std::uint64_t r,
                       int* comparisons) {
    std::size_t lo = 0, hi = prefix.size();  // answer is in [lo, hi)
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (comparisons) ++*comparisons;
        if (prefix[mid] > r) hi = mid;  // mid could be the answer
        else lo = mid + 1;              // answer is to the right
    }
    if (lo == prefix.size()) throw std::out_of_range("r must be smaller than the total weight");
    return lo;
}

slot.pick_linear.code:
std::size_t pickLinear(const std::vector<std::uint32_t>& weights, std::uint64_t r,
                       int* comparisons) {
    for (std::size_t i = 0; i < weights.size(); ++i) {
        if (comparisons) ++*comparisons;
        if (r < weights[i]) return i;  // r landed inside this symbol's slice
        r -= weights[i];               // skip past this slice
    }
    throw std::out_of_range("r must be smaller than the total weight");
}

slot.rng_lcg.code:
// Linear congruential generator: x = a*x + c (mod 2^32).
// Fast and tiny, but its LOW bits are weak: the lowest bit just alternates.
class Lcg32 {
public:
    explicit Lcg32(std::uint32_t seed) : state_(seed) {}
    std::uint32_t next() {
        state_ = 1664525u * state_ + 1013904223u;  // unsigned overflow wraps = mod 2^32
        return state_;
    }

private:
    std::uint32_t state_;
};

slot.rng_pcg.code:
// PCG32 (O'Neill, pcg-random.org): an LCG on 64 bits, then a permutation
// that scrambles the output. Small, fast and statistically strong.
class Pcg32 {
public:
    Pcg32(std::uint64_t seed, std::uint64_t sequence) : inc_((sequence << 1u) | 1u) {
        next();
        state_ += seed;
        next();
    }
    std::uint32_t next() {
        const std::uint64_t old = state_;
        state_ = old * 6364136223846793005ULL + inc_;
        const auto xorshifted = static_cast<std::uint32_t>(((old >> 18u) ^ old) >> 27u);
        const auto rot = static_cast<std::uint32_t>(old >> 59u);
        return (xorshifted >> rot) | (xorshifted << ((32u - rot) & 31u));
    }

private:
    std::uint64_t state_ = 0;
    std::uint64_t inc_;
};

slot.rng_xorshift.code:
// Marsaglia's xorshift32: three shift-and-xor steps. Never outputs 0
// (so the seed must not be 0). Period 2^32 - 1.
class XorShift32 {
public:
    explicit XorShift32(std::uint32_t seed) : state_(seed == 0 ? 0x9E3779B9u : seed) {}
    std::uint32_t next() {
        std::uint32_t x = state_;
        x ^= x << 13;
        x ^= x >> 17;
        x ^= x << 5;
        return state_ = x;
    }

private:
    std::uint32_t state_;
};

slot.rtp_exact.code:
// Return To Player, exactly: try EVERY combination of stops once.
// Each combination is equally likely, so the average pay is the RTP.
RtpReport exactRtpCentreLine(const ReelGame& g) {
    if (g.reels.size() != 3) throw std::invalid_argument("this brute force is written for 3 reels");
    RtpReport r;
    const std::vector<int> centre = {1, 1, 1};
    const int n0 = static_cast<int>(g.reels[0].size());
    const int n1 = static_cast<int>(g.reels[1].size());
    const int n2 = static_cast<int>(g.reels[2].size());
    for (int a = 0; a < n0; ++a) {
        for (int b = 0; b < n1; ++b) {
            for (int c = 0; c < n2; ++c) {
                const LineResult win = evaluateLine(g, window(g, {a, b, c}), centre);
                ++r.combos;
                if (win.pay > 0) ++r.winningCombos;
                r.totalPay += static_cast<std::uint64_t>(win.pay);
                r.sumSquares += static_cast<long double>(win.pay) * win.pay;
            }
        }
    }
    r.rtp = static_cast<double>(r.totalPay) / static_cast<double>(r.combos);
    r.hitFrequency = static_cast<double>(r.winningCombos) / static_cast<double>(r.combos);
    const long double mean = static_cast<long double>(r.rtp);
    r.stdDev = static_cast<double>(std::sqrt(r.sumSquares / r.combos - mean * mean));
    return r;
}

slot.rtp_sim.code:
// Monte Carlo: play many random spins and average the pay.
// The error shrinks like 1 / sqrt(spins): 100x more spins = 10x more accurate.
double simulateRtp(const ReelGame& g, std::uint64_t spins, Pcg32& rng, Recorder& rec) {
    const std::vector<int> centre = {1, 1, 1};
    std::vector<int> stops(g.reels.size());
    std::uint64_t paid = 0;
    for (std::uint64_t i = 1; i <= spins; ++i) {
        for (std::size_t k = 0; k < stops.size(); ++k) {
            const auto len = static_cast<std::uint32_t>(g.reels[k].size());
            stops[k] = static_cast<int>(uniformBelow(rng, len));  // fair stop
        }
        paid += static_cast<std::uint64_t>(evaluateLine(g, window(g, stops), centre).pay);
    }
    return static_cast<double>(paid) / static_cast<double>(spins);
}

slot.state_machine.code:
// Every event checks "is this allowed RIGHT NOW?" before changing state.
// That one rule prevents a whole class of bugs: double spins, paying twice,
// spinning with no credits...
bool SlotMachine::pressSpin(int bet) {
    if (state_ == State::Idle) {
        if (bet <= 0 || bet > credits_) return false;  // can't afford it
        credits_ -= bet;
        bet_ = bet;
        inFreeSpin_ = false;
    } else if (state_ == State::FreeSpins) {
        --freeSpins_;  // free: no credits taken
        inFreeSpin_ = true;
    } else {
        return false;  // ignored: reels already moving, or a win is showing
    }
    state_ = State::Spinning;
    emit("spin");
    return true;
}

bool SlotMachine::reelsStopped(const std::vector<int>& stops) {
    if (state_ != State::Spinning) return false;
    state_ = State::Evaluating;
    screen_ = window(game_, stops);
    const LineResult win = evaluateLine(game_, screen_, {1, 1, 1});
    lastWin_ = win.pay * bet_;
    credits_ += lastWin_;
    if (win.count == 3 && game_.symbols[win.symbol].id == "BELL") {
        freeSpins_ += 3;  // bonus trigger: three bells
        emit("bonus +3 free spins");
    }
    if (lastWin_ > 0) {
        state_ = State::WinShow;
        emit(cat("win ", lastWin_));
    } else {
        finishRound();
    }
    return true;
}

bool SlotMachine::winShown() {
    if (state_ != State::WinShow) return false;
    finishRound();
    return true;
}

void SlotMachine::finishRound() {
    state_ = freeSpins_ > 0 ? State::FreeSpins : State::Idle;
}

slot.uniform_below.code:
// A fair number in [0, n). `rng() % n` is BIASED when 2^32 is not a
// multiple of n: some results get one extra chance. Fix: throw away the
// few raw values at the top that would cause the imbalance.
template <Rng32 G>
std::uint32_t uniformBelow(G& rng, std::uint32_t n) {
    const std::uint32_t limit = static_cast<std::uint32_t>(-n) % n;  // = 2^32 mod n
    while (true) {
        const std::uint32_t r = rng.next();
        if (r >= limit) return r % n;  // the rest is an exact multiple of n
    }
}

slot.ways.code:
// "243 ways" on 5 reels x 3 rows: any position on reel 1, then any on
// reel 2, ... (3 x 3 x 3 x 3 x 3 = 243 paths). A symbol pays for every
// path that matches from the left, so we MULTIPLY the matches per reel.
std::vector<WaysResult> evaluateWays(const ReelGame& g, const Screen& s) {
    std::vector<WaysResult> wins;
    for (int sym = 0; sym < static_cast<int>(g.symbols.size()); ++sym) {
        if (sym == g.wild) continue;
        long long ways = 1;
        int reels = 0;
        for (std::size_t k = 0; k < g.reels.size(); ++k) {
            int matches = 0;
            for (int row = 0; row < g.rows; ++row) {
                if (s[row][k] == sym || s[row][k] == g.wild) ++matches;
            }
            if (matches == 0) break;  // the chain stops at the first reel without it
            ways *= matches;
            ++reels;
        }
        const int pay = g.paytable[sym][reels];
        if (pay > 0) wins.push_back({sym, reels, ways, pay * ways});
    }
    return wins;
}

slot.window.code:
// A reel strip is a CIRCULAR array: after the last stop comes the first.
// The % (modulo) operator does the wrap-around for us.
Screen window(const ReelGame& g, const std::vector<int>& stops) {
    Screen screen(g.rows, std::vector<int>(g.reels.size()));
    for (std::size_t reel = 0; reel < g.reels.size(); ++reel) {
        const auto& strip = g.reels[reel];
        const int len = static_cast<int>(strip.size());
        for (int row = 0; row < g.rows; ++row) {
            screen[row][reel] = strip[(stops[reel] + row) % len];
        }
    }
    return screen;
}

sort.bubble.code:
void bubbleSort(std::vector<int>& a, Recorder& rec) {
    const std::size_t n = a.size();
    for (std::size_t pass = 0; pass + 1 < n; ++pass) {
        bool swapped = false;
        for (std::size_t j = 0; j + 1 < n - pass; ++j) {
            if (a[j] > a[j + 1]) {
                std::swap(a[j], a[j + 1]);
                swapped = true;
            }
        }
        if (!swapped) break;  // nothing moved: already sorted
    }
}

